def choose_move(observation):
    def clamp(v):
        return -1 if v < -1 else (1 if v > 1 else v)

    def get_any(d, keys, default=None):
        if not isinstance(d, dict):
            return default
        for k in keys:
            if k in d:
                return d.get(k)
        return default

    def as_pos(v):
        if isinstance(v, dict):
            x = get_any(v, ["x", "col", "c", "px", "pos_x", "position_x"])
            y = get_any(v, ["y", "row", "r", "py", "pos_y", "position_y"])
            if x is not None and y is not None:
                return [x, y]
            p = get_any(v, ["pos", "position", "loc", "location"])
            return as_pos(p)
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return [v[0], v[1]]
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def sign(n):
        return -1 if n < 0 else (1 if n > 0 else 0)

    def listify(v):
        if v is None:
            return []
        if isinstance(v, list):
            return v
        if isinstance(v, tuple):
            return list(v)
        return [v]

    def find_self(obs):
        for key in ["self", "agent", "player", "unit", "me", "hero"]:
            p = as_pos(obs.get(key)) if isinstance(obs, dict) else None
            if p is not None:
                return p
        for key in ["position", "pos", "location", "loc"]:
            p = as_pos(obs.get(key)) if isinstance(obs, dict) else None
            if p is not None:
                return p
        return [0, 0]

    def extract_entities(obs):
        out = []
        if not isinstance(obs, dict):
            return out
        for key in ["entities", "objects", "items", "targets", "units", "agents", "enemies", "resources", "nodes"]:
            arr = obs.get(key)
            for e in listify(arr):
                p = as_pos(e)
                if p is not None:
                    kind = ""
                    if isinstance(e, dict):
                        kind = str(get_any(e, ["type", "kind", "name", "role", "team"], ""))
                    out.append((p, kind, e))
        return out

    def walkable_move_toward(src, dst):
        dx = sign(dst[0] - src[0])
        dy = sign(dst[1] - src[1])
        if abs(dst[0] - src[0]) > abs(dst[1] - src[1]):
            return [dx, 0] if dx != 0 else [0, dy]
        return [0, dy] if dy != 0 else [dx, 0]

    me = find_self(observation)
    entities = extract_entities(observation)

    # Generic nearby signals
    resources = []
    enemies = []
    allies = []
    hazards = []
    goals = []

    for p, kind, raw in entities:
        k = kind.lower()
        dist = manhattan(me, p)
        if any(s in k for s in ["resource", "food", "coin", "gem", "material", "pickup", "supply"]):
            resources.append((dist, p, raw))
        elif any(s in k for s in ["enemy", "opponent", "hostile", "predator", "hunter"]):
            enemies.append((dist, p, raw))
        elif any(s in k for s in ["ally", "friend", "teammate"]):
            allies.append((dist, p, raw))
        elif any(s in k for s in ["hazard", "trap", "wall", "obstacle", "lava", "water"]):
            hazards.append((dist, p, raw))
        else:
            goals.append((dist, p, raw))

    resources.sort(key=lambda t: t[0])
    enemies.sort(key=lambda t: t[0])
    hazards.sort(key=lambda t: t[0])
    goals.sort(key=lambda t: t[0])

    # Read common scalar hints
    health = get_any(observation, ["health", "hp", "life", "energy", "stamina"], None)
    max_health = get_any(observation, ["max_health", "max_hp", "max_life", "max_energy"], None)
    score = get_any(observation, ["score", "points", "value"], 0)

    low_health = False
    if isinstance(health, (int, float)):
        if isinstance(max_health, (int, float)) and max_health > 0:
            low_health = health <= max_health * 0.4
        else:
            low_health = health <= 3

    # Danger avoidance
    if enemies:
        d, ep, raw = enemies[0]
        if d <= 2:
            # If weak, flee; else pressure the enemy a bit.
            enemy_strength = None
            if isinstance(raw, dict):
                enemy_strength = get_any(raw, ["health", "hp", "power", "strength", "score"], None)
            stronger = False
            if isinstance(health, (int, float)) and isinstance(enemy_strength, (int, float)):
                stronger = health > enemy_strength
            if low_health or not stronger:
                return [clamp(me[0] - ep[0]), clamp(me[1] - ep[1])]
            return walkable_move_toward(me, ep)

    # Resource collection: go to closest resource if any
    if resources:
        d, rp, raw = resources[0]
        if low_health and enemies:
            # keep distance while still drifting toward resource
            ex, ey = enemies[0][1]
            move = [sign(me[0] - ex), sign(me[1] - ey)]
            if move == [0, 0]:
                move = walkable_move_toward(me, rp)
            return move
        return walkable_move_toward(me, rp)

    # Territory control / generic objective: move to closest non-self target
    if goals:
        # Prefer farther/frontier-ish target if no obvious resource
        best = goals[0][1]
        if allies and len(goals) > 1:
            # bias away from crowding
            best = goals[min(1, len(goals) - 1)][1]
        return walkable_move_toward(me, best)

    # Explore: use observation hints or deterministic spiral-like drift
    turn = get_any(observation, ["step", "turn", "tick", "time"], 0)
    if isinstance(turn, int):
        dirs = [[1, 0], [0, 1], [-1, 0], [0, -1]]
        return dirs[turn % 4]

    # Default cautious move
    if hazards:
        h = hazards[0][1]
        return [sign(me[0] - h[0]), sign(me[1] - h[1])]

    return [0, 0]

